const $=id=>document.getElementById(id);
const uuid=()=>crypto.randomUUID?.()||'id-'+Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db,state,activeFolder=null,selected=null,tab='midjourney',image=null,toastTimer,saveQueue=Promise.resolve(),drawToken=0;
const models={midjourney:'Midjourney',minimax:'MiniMax H3',seedance:'Seedance',kling:'Kling'};
const cameraText={handheld:'Restrained handheld micro-movement with subtle natural shake; hold the subject in readable framing.',static:'Camera completely locked and static: no shake, drift, pan, orbit, or zoom.',push:'Smooth, slow gimbal push-in toward the subject; maintain the viewing angle with no shake.',pull:'Smooth, slow gimbal pull-back away from the subject; keep the subject centered with no shake.',track:'Track laterally alongside the subject at a matching pace, keeping the subject framed with subtle handheld micro-motion and realistic parallax.',kinetic:'Kinetic handheld motion with natural micro-jitters and small bumps; keep the action readable.'};
function toast(s){const host=[...document.querySelectorAll('dialog[open]')].at(-1)||document.body;host.appendChild($('toast'));$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4500)}
function project(){return state.projects.find(p=>p.id===state.active)||state.projects[0]}
function shot(){return project().shots.find(s=>s.id===selected)}
async function saveReplikatedShot(item,projectId,folderId,title){const p=state.projects.find(p=>p.id===projectId);if(!p)throw Error('Choose an existing storyboard.');if(folderId&&!(p.folders||[]).some(f=>f.id===folderId))throw Error('Choose an existing folder.');let s=p.shots.find(s=>s.replikatorId===item.id&&s.folderId===folderId);if(!s){s={...freshShot(title),src:item.src,width:item.width,height:item.height,folderId,replikatorId:item.id,notes:'Style Replikator: '+item.style};p.shots.push(s);try{await save()}catch(e){p.shots=p.shots.filter(x=>x.id!==s.id);throw e;}}state.active=p.id;activeFolder=folderId;await save();showLibrary(false);render();openShot(s.id);toast('Saved to storyboard. Analyse this frame, then generate your video prompt.');}
function freshShot(title='Untitled shot'){return {id:uuid(),title,scene:'',notes:'',action:'',duration:5,camera:'handheld',blur:false,status:'draft',resizeMode:'pad',cropX:50,cropY:50,resolution:1920,src:null,width:0,height:0,prompts:{}}}
async function init(){try{db=await new Promise((resolve,reject)=>{const req=indexedDB.open('frameflow-studio',1);req.onupgradeneeded=()=>req.result.createObjectStore('workspace');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});state=await new Promise((resolve,reject)=>{const req=db.transaction('workspace').objectStore('workspace').get('state');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});if(!state){const p={id:uuid(),title:'My first storyboard',shots:[]};state={version:1,active:p.id,projects:[p]};await save()}if(migrateExtractedFolders())await save();render();setupReplikator({state,save,addToStoryboard:saveReplikatedShot,show:()=>{showLibrary(false);$('storyboardMain').hidden=true;$('replikatorMain').hidden=false;$('boardNav').classList.remove('active');$('replikatorNav').classList.add('active');$('crumb').textContent='Style Replikator';}});showStoryboards()}catch(e){console.error('Workspace initialization failed:',e.message);document.querySelector('main').innerHTML='<h2>Browser storage is unavailable</h2><p>Allow site data in your browser and reload to use this workspace.</p>';toast('Could not open browser storage.')}}
function save(){if(!db)return Promise.resolve();$('saveState').textContent='Saving…';const snapshot=structuredClone(state);const write=()=>new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(snapshot,'state');tx.oncomplete=()=>{$('saveState').textContent='Saved in this browser';resolve()};tx.onerror=tx.onabort=()=>{$('saveState').textContent='Not saved — export a backup';toast('Storage is full or unavailable. Export a backup now.');reject(tx.error)}});saveQueue=saveQueue.catch(()=>{}).then(write);saveQueue.catch(()=>{});return saveQueue}
function renderProjectNav(){const current=project();$('projects').innerHTML=state.projects.map(p=>`<button class="project-item ${p.id===current.id&&!$('storyboardMain').hidden?'selected':''}" data-project="${esc(p.id)}"><span class="dot"></span><span>${esc(p.title)}</span></button>`).join('');}
function showStoryboards(){showLibrary(false);$('storyboardMain').hidden=true;$('storyboardLibrary').hidden=false;$('crumb').textContent='Storyboards';renderProjectNav();$('storyboardGrid').innerHTML=state.projects.map(p=>`<button class="shot-card storyboard-project" data-project="${esc(p.id)}" aria-label="Open storyboard ${esc(p.title)}"><span class="folder-cover"><span class="folder-previews">${p.shots.filter(s=>s.src).slice(0,3).map(s=>`<img src="${s.src}" alt="" loading="lazy">`).join('')}</span><span class="folder-symbol">▤</span></span><span class="card-content"><strong class="card-title">${esc(p.title)}</strong><span class="card-bottom"><span>${(p.folders||[]).length} folders</span><span>${p.shots.length} frames</span></span></span></button>`).join('');}
function render(){const p=project();const folder=(p.folders||[]).find(f=>f.id===activeFolder);if(!folder)activeFolder=null;const shots=p.shots.filter(s=>activeFolder?s.folderId===activeFolder:!s.folderId);$('folderBar').hidden=!folder;$('folderTitle').value=folder?.title||'';$('folderCount').textContent=folder?shots.length+' frames':'';$('projectTitle').value=p.title;$('crumb').textContent=p.title;$('projectCount').textContent=state.projects.length;renderProjectNav();$('shotCount').textContent=String(p.shots.length).padStart(2,'0');$('totalDuration').textContent=fmt(p.shots.reduce((a,s)=>a+s.duration,0))+'s';$('readyCount').textContent=String(p.shots.filter(s=>s.status==='ready').length).padStart(2,'0');const folders=activeFolder?'':(p.folders||[]).map(f=>{const items=p.shots.filter(s=>s.folderId===f.id);return `<article class="shot-card folder-card"><button class="folder-cover" data-folder="${esc(f.id)}" aria-label="Open folder ${esc(f.title)}"><div class="folder-previews">${items.filter(s=>s.src).slice(0,3).map(s=>`<img src="${s.src}" alt="" loading="lazy">`).join('')}</div><span class="folder-symbol">▤</span></button><div class="card-content"><button class="card-title" data-folder="${esc(f.id)}">${esc(f.title)}</button><div class="card-bottom"><span>Folder</span><span>${items.length} frames</span></div></div></article>`}).join('');
$('board').innerHTML=folders+shots.map((s,i)=>`<article class="shot-card"><button class="thumb" data-open="${s.id}" aria-label="Open ${esc(s.title)}">${s.src?`<img src="${s.src}" alt="${esc(s.title)}" loading="lazy">`:`<div class="placeholder">${String(i+1).padStart(2,'0')}</div>`}<span class="shot-num">SHOT ${String(i+1).padStart(2,'0')}</span><span class="duration-badge">${fmt(s.duration)}s</span></button><div class="card-content"><button class="card-title" data-open="${s.id}">${esc(s.title)}</button><div class="card-bottom"><span class="badge ${s.status}">${s.status}</span><span>${Object.values(s.prompts).filter(Boolean).length}/4 prompts</span><span class="card-order"><button data-move="${s.id}" data-dir="-1" aria-label="Move ${esc(s.title)} earlier" ${i===0?'disabled':''}>←</button><button data-move="${s.id}" data-dir="1" aria-label="Move ${esc(s.title)} later" ${i===shots.length-1?'disabled':''}>→</button></span></div></div></article>`).join('')||`<section class="empty"><h2>${activeFolder?'This folder is empty.':'Your next story starts here.'}</h2><p>${activeFolder?'Add images to build this storyboard.':'Upload images or send a batch from Frame Extractor.'}</p><button class="button primary" id="emptyUpload">＋ Add images</button></section>`;$('emptyUpload')?.addEventListener('click',()=>$('files').click());if(folder)$('crumb').textContent=p.title+' / '+folder.title;}

const fmt=n=>Number(Number(n).toFixed(2)).toString();
$('projects').onclick=e=>{const b=e.target.closest('[data-project]');if(b){activeFolder=b.dataset.folder||null;state.active=b.dataset.project;showLibrary(false);save();render()}};
$('newProject').onclick=()=>{const p={id:uuid(),title:`Storyboard ${state.projects.length+1}`,shots:[]};state.projects.push(p);activeFolder=null;state.active=p.id;showLibrary(false);save();render();$('projectTitle').focus();$('projectTitle').select()};
$('projectTitle').oninput=e=>{project().title=e.target.value||'Untitled storyboard';$('crumb').textContent=project().title;renderProjectNav();save()};$('projectTitle').onchange=render;
$('boardNav').onclick=showStoryboards;
$('backToStoryboards').onclick=showStoryboards;
$('storyboardGrid').onclick=$('projects').onclick;
$('libraryNewProject').onclick=()=>$('newProject').click();
$('uploadBtn').onclick=()=>$('files').click();$('replaceImage').onclick=()=>$('replacement').click();
$('addShot').onclick=()=>{const s={...freshShot(`Shot ${project().shots.length+1}`),folderId:activeFolder};project().shots.push(s);save();render();openShot(s.id)};
async function readFile(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error(`${file.name}: use PNG, JPG, or WebP.`);if(file.size>25*1024*1024)throw Error(`${file.name}: exceeds 25 MB.`);const src=await new Promise((r,j)=>{const fr=new FileReader();fr.onload=()=>r(fr.result);fr.onerror=()=>j(Error('Could not read image.'));fr.readAsDataURL(file)});const im=await loadImage(src);return {src,width:im.naturalWidth,height:im.naturalHeight}}
function loadImage(src){return new Promise((r,j)=>{const im=new Image();im.onload=()=>r(im);im.onerror=()=>j(Error('This image could not be decoded.'));im.src=src})}
async function upload(files){const p=project();let added=0;for(const f of files){try{const data=await readFile(f);p.shots.push({...freshShot(f.name.replace(/\.[^.]+$/,'')),...data,folderId:activeFolder});added++}catch(e){toast(e.message)}}if(added){try{await save();render();if(added===1&&!$('editor').open)openShot(p.shots.at(-1).id);toast(`${added} image${added===1?'':'s'} added to storyboard.`)}catch{render()}}}
$('files').onchange=async e=>{const files=Array.from(e.target.files);e.target.value='';await upload(files)};
$('replacement').onchange=async e=>{const s=shot(),f=e.target.files[0];e.target.value='';if(!f||!s)return;try{Object.assign(s,await readFile(f));s.scene='';delete s.analysisEvidence;$('scene').value='';syncPromptButtons();await save();render();if(shot()?.id===s.id)await drawPreview();toast('Reference replaced. Existing prompts kept for review.')}catch(e){toast(e.message)}};
window.addEventListener('dragover',e=>{if([...e.dataTransfer.types].includes('Files')){e.preventDefault();document.body.classList.add('dragging')}});window.addEventListener('dragleave',e=>{if(!e.relatedTarget)document.body.classList.remove('dragging')});window.addEventListener('drop',e=>{e.preventDefault();document.body.classList.remove('dragging');if(e.dataTransfer.files.length)upload([...e.dataTransfer.files])});
$('board').onclick=e=>{const folder=e.target.closest('[data-folder]');if(folder){activeFolder=folder.dataset.folder;render();return}const open=e.target.closest('[data-open]');if(open)openShot(open.dataset.open);const move=e.target.closest('[data-move]');if(move){const a=project().shots,visible=a.filter(s=>activeFolder?s.folderId===activeFolder:!s.folderId),at=visible.findIndex(s=>s.id===move.dataset.move),next=at+Number(move.dataset.dir);if(next<0||next>=visible.length)return;const i=a.indexOf(visible[at]),j=a.indexOf(visible[next]);[a[i],a[j]]=[a[j],a[i]];save();render()}};
function openShot(id){$('promptFeedback').textContent='';$('analysisFeedback').textContent='Analyse your frame, then generate a prompt.';selected=id;const s=shot();$('shotLabel').textContent='SHOT '+String(project().shots.indexOf(s)+1).padStart(2,'0');for(const f of ['title','scene','notes','action','duration','camera','resizeMode','cropX','cropY','resolution','status'])$(f==='title'?'shotTitle':f).value=s[f];$('blur').checked=s.blur;setTab('minimax');$('editor').showModal();drawPreview();syncPromptButtons()}
function closeEditor(){$('editor').close();render()}
$('closeEditor').onclick=closeEditor;$('editor').addEventListener('close',()=>{render();selected=null;drawToken++});
for(const [id,key] of Object.entries({shotTitle:'title',scene:'scene',notes:'notes',action:'action',duration:'duration',camera:'camera',resizeMode:'resizeMode',cropX:'cropX',cropY:'cropY',resolution:'resolution',status:'status',blur:'blur'})){$(id).addEventListener(id==='duration'?'change':'input',()=>{const s=shot();if(!s)return;let v=$(id).value;if(['duration','cropX','cropY','resolution'].includes(id))v=Number(v);if(id==='duration'){if(!Number.isFinite(v)||v<1||v>120){v=5;$(id).value=v;toast('Use a duration between 1 and 120 seconds.')}}if(id==='blur')v=$(id).checked;s[key]=v;save();if(['resizeMode','cropX','cropY','resolution'].includes(id))drawPreview();if(id==='status')render();if(id==='scene')syncPromptButtons()})}
function setTab(t){tab=t;$('promptHelp').textContent={minimax:'MiniMax H3: timed action beats, natural performance, and separate camera direction.',kling:'Kling: concise subject-and-movement direction, with relevant background motion and camera behavior.',seedance:'Seedance: scene, ordered action, and camera direction; sound only when requested.',midjourney:'Midjourney: still-image composition with your selected style reference.'}[t]+' Powered by Livepeer; generation uses account credits. Creates a prompt, not a video.';$('mjStylePicker').hidden=t!=='midjourney';renderStyles();$('modelSelect').value=t;document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));$('videoControls').hidden=t==='midjourney';$('mjNote').hidden=t!=='midjourney';$('promptOutput').value=shot()?.prompts[t]||'';updateCount()}
$('modelSelect').onchange=e=>setTab(e.target.value);
function updateCount(){$('charCount').textContent=$('promptOutput').value.length+' characters'}
$('promptOutput').oninput=()=>{const s=shot();if(s){s.prompts[tab]=$('promptOutput').value;save();updateCount()}};
function motion(s){const action=s.action.trim()||'Keep the pose consistent with subtle breathing and natural environmental movement.';const blur=s.blur?'Use photographic slow-shutter blur from relative movement in the surroundings; keep the principal subject comparatively sharp and readable, allowing plausible local blur on moving limbs. No artificial smear.':'';return `${action} ${cameraText[s.camera]} ${blur} Preserve identity, proportions, clothing, props, lighting, and spatial continuity. Keep human movement physically believable with natural balance, contact, and understated expression.`}
function build(s,model){const scene=s.scene.trim();if(model==='midjourney'){if(!scene)throw Error('Add a scene description or analyze your reference image first.');return `${scene.replace(/\s*--ar\s+\S+/g,'').trim()}. Faithful composition, consistent subject proportions, coherent perspective, detailed natural textures. --ar 16:9`;}if(!scene&&!s.src&&!s.action.trim())throw Error('Add a reference, scene description, or action first.');const context=scene||'Use the supplied reference image as the first frame.';const segment=`0–${fmt(s.duration)}s: ${motion(s)}`;if(model==='seedance')return `Seedance | ${fmt(s.duration)}s | Single continuous shot\nReference: ${context}\n${segment}\nOne uninterrupted action; no cuts, fades, or unrequested camera changes.`;if(model==='kling')return `Kling | ${fmt(s.duration)}s\nScene / first frame: ${context}\n${segment}\nContinuous shot. Avoid morphing, duplicated limbs, foot sliding, or abrupt pose changes.`;return `MiniMax H3 | ${fmt(s.duration)}s | Continuous shot\n${context}\n${segment}\nNo cuts, fades, or unrequested angle changes.`}
function syncPromptButtons(){const s=shot();$('analyze').disabled=promptBusy||!s?.src;$('buildPrompt').disabled=promptBusy||!s?.scene?.trim();$('buildPrompt').title=s?.scene?.trim()?'Generate from this analysis':'Analyse the frame or enter a description first';}
$('buildPrompt').onclick=async()=>{const target=tab,s=shot();if(!s||promptBusy)return;if(!s.scene.trim())return toast('Analyse the frame first.');promptBusy=true;syncPromptButtons();$('buildPrompt').textContent='Generating…';try{await generateFramePrompts(s,[target]);if(shot()?.id===s.id&&tab===target){$('promptOutput').value=s.prompts[target];$('status').value=s.status;updateCount()}toast('Prompt saved.')}catch(e){$('promptFeedback').textContent=e.message;toast(e.message)}finally{promptBusy=false;$('buildPrompt').textContent='Generate prompt';syncPromptButtons()}};

async function copy(text){if(!text.trim())return toast('Build a prompt first.');try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.')}catch{toast('Clipboard unavailable. Select the prompt text and copy it.')}}
$('copyPrompt').onclick=()=>copy($('promptOutput').value);
async function drawPreview(){const token=++drawToken,s=shot();if(!s)return;$('cropControls').hidden=s.resizeMode!=='crop';$('noPreview').hidden=!!s.src;$('downloadFrame').disabled=!s.src;$('dimensions').textContent=s.src?`${s.width} × ${s.height} original`:'No reference image';const c=$('preview');c.width=s.resolution;c.height=s.resolution*9/16;const ctx=c.getContext('2d');ctx.fillStyle='#000';ctx.fillRect(0,0,c.width,c.height);if(!s.src)return;try{const im=await loadImage(s.src);if(token!==drawToken)return;image=im;paint(c,im,s)}catch(e){toast(e.message)}}
function paint(c,im,s){const ctx=c.getContext('2d');ctx.fillStyle='#000';ctx.fillRect(0,0,c.width,c.height);const scale=s.resizeMode==='crop'?Math.max(c.width/im.naturalWidth,c.height/im.naturalHeight):Math.min(c.width/im.naturalWidth,c.height/im.naturalHeight);const w=im.naturalWidth*scale,h=im.naturalHeight*scale;const x=(c.width-w)*(s.resizeMode==='crop'?s.cropX/100:.5),y=(c.height-h)*(s.resizeMode==='crop'?s.cropY/100:.5);ctx.imageSmoothingQuality='high';ctx.drawImage(im,x,y,w,h)}
function safeName(t){return (t||'storyboard').replace(/[^a-z0-9_-]/gi,'-').slice(0,70)}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
$('downloadFrame').onclick=async()=>{const s=shot();if(!s?.src)return;try{const c=document.createElement('canvas');c.width=s.resolution;c.height=s.resolution*9/16;paint(c,await loadImage(s.src),s);c.toBlob(b=>{if(b){download(b,`${safeName(s.title)}-${c.width}x${c.height}.png`);toast('16:9 PNG exported.')}else toast('Image export failed.')},'image/png')}catch(e){toast(e.message)}};
$('deleteShot').onclick=()=>{const s=shot();if(!s||!window.confirm('Delete this shot and its prompts?'))return;const p=project(),i=p.shots.indexOf(s);p.shots.splice(i,1);save();closeEditor();toast('Shot removed. Export backups to preserve previous versions.')};
$('backupBtn').onclick=()=>download(new Blob([JSON.stringify(state)],{type:'application/json'}),'workflow-backup.json');
$('restoreBtn').onclick=()=>$('importFile').click();
function validatedState(raw){if(raw?.version!==1||!Array.isArray(raw.projects)||!raw.projects.length||raw.projects.length>100)throw Error('Not a supported Workflow backup.');const str=(v,n=50000)=>typeof v==='string'?v.slice(0,n):'';const projects=raw.projects.map(p=>{if(!Array.isArray(p.shots)||p.shots.length>2000)throw Error('Invalid shot list.');const folderMap=new Map();const folders=(Array.isArray(p.folders)?p.folders:[]).slice(0,2000).filter(f=>f&&typeof f.id==='string'&&!folderMap.has(f.id)).map(f=>{const id=uuid();folderMap.set(f.id,id);return {id,title:str(f.title,200)||'Storyboard folder'}});return {folders,id:uuid(),title:str(p.title,200)||'Imported storyboard',livepeerJobs:Array.isArray(p.livepeerJobs)?p.livepeerJobs.slice(-100).filter(j=>j&&/^job_[a-z0-9]{6,32}$/.test(j.id)).map(j=>({id:j.id,created:Number(j.created)||Date.now(),brief:str(j.brief,5000),status:str(j.status,50),result:typeof j.result==='object'?j.result:{}})):[],shots:p.shots.map(s=>{const r=freshShot(str(s.title,200)||'Imported shot');r.folderId=folderMap.get(s.folderId)||null;if(typeof s.replikatorId==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(s.replikatorId))r.replikatorId=s.replikatorId;for(const k of ['scene','action','notes'])r[k]=str(s[k]);r.duration=Number.isFinite(s.duration)?Math.max(1,Math.min(120,s.duration)):5;r.camera=Object.hasOwn(cameraText,s.camera)?s.camera:'handheld';r.blur=!!s.blur;r.status=['draft','prompted','ready'].includes(s.status)?s.status:'draft';r.resizeMode=s.resizeMode==='crop'?'crop':'pad';r.resolution=s.resolution===3840?3840:1920;for(const k of ['cropX','cropY'])r[k]=Number.isFinite(s[k])?Math.max(0,Math.min(100,s[k])):50;r.mjStyle=[...mjStyles,...validateCustomStyles(raw.customStyles||[])].some(x=>x.code===s.mjStyle)?s.mjStyle:'';for(const k of Object.keys(models))r.prompts[k]=str(s.prompts?.[k]);if(s.src){if(typeof s.src!=='string'||!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(s.src))throw Error('Backup contains an unsupported image.');r.src=s.src;r.width=Number(s.width)||0;r.height=Number(s.height)||0;}if(s.promptEvidence&&typeof s.promptEvidence==='object')r.promptEvidence=s.promptEvidence;return r})}});return projects}
$('importFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>300*1024*1024)throw Error('Backup exceeds 300 MB.');const projects=validatedState(JSON.parse(await f.text()));const raw=JSON.parse(await f.text());const incomingGallery=validateGallery(raw.replikatorGallery);const mergedGallery=[...(state.replikatorGallery||[])];for(const image of incomingGallery)if(!mergedGallery.some(x=>x.id===image.id||x.url&&x.url===image.url))mergedGallery.push(image);validateGallery(mergedGallery);const incomingProfiles=validateProfiles(raw.replikatorProfiles);const mergedProfiles=[...(state.replikatorProfiles||[])];for(const profile of incomingProfiles)if(!mergedProfiles.some(p=>p.id===profile.id))mergedProfiles.push(profile);validateProfiles(mergedProfiles);const importedStyles=validateCustomStyles(raw.customStyles||[]);const mergedStyles=[...(state.customStyles||[])];for(const style of importedStyles)if(!mergedStyles.some(x=>x.code===style.code))mergedStyles.push(style);validateCustomStyles(mergedStyles);const restored=validateReferences(raw.references||[]);const keys=new Set((state.references||[]).map(r=>r.key));state.references||=[];for(const ref of restored)if(!keys.has(ref.key)){state.references.push(ref);keys.add(ref.key)}state.replikatorGallery=mergedGallery;state.replikatorProfiles=mergedProfiles;state.customStyles=mergedStyles;state.projects.push(...projects);migrateExtractedFolders();activeFolder=null;state.active=projects[0].id;await save();render();renderReferences();toast(`Imported ${projects.length} storyboard(s). Existing work kept.`)}catch(e){toast(e.message)}};
$('exportPrompts').onclick=()=>{const p=project();if(!p.shots.length)return toast('Add some shots first.');let t=`${p.title}\n${p.shots.length} shots · ${fmt(p.shots.reduce((a,s)=>a+s.duration,0))} seconds\n\n`;p.shots.forEach((s,i)=>{t+=`SHOT ${i+1}: ${s.title}\n${s.notes?`Notes: ${s.notes}\n`:''}`;for(const [k,label]of Object.entries(models))t+=`\n${label}\n${s.prompts[k]||'(No saved prompt yet)'}\n`;t+='\n---\n\n'});download(new Blob([t],{type:'text/plain'}),safeName(p.title)+'-prompts.txt')};
function montageText(){const p=project();let n=0;return `${$('montageModel').value} | ${fmt(p.shots.reduce((a,s)=>a+s.duration,0))}s montage | ${p.shots.length} shots\nUse the reference images in storyboard order. Direct cuts at each boundary; no fades. Preserve the appearance of recurring subjects across shots.\n\n`+p.shots.map((s,i)=>{const start=n;n+=s.duration;return `${fmt(start)}–${fmt(n)}s — Shot ${i+1}: ${s.title}\n${s.scene||'Use the corresponding reference image.'}\n${motion(s)}`}).join('\n\n')}
$('montageBtn').onclick=()=>{if(!project().shots.length)return toast('Add storyboard shots to build a montage.');$('montageOutput').value=montageText();$('montage').showModal()};$('montageModel').onchange=()=>$('montageOutput').value=montageText();$('copyMontage').onclick=()=>copy($('montageOutput').value);
