const platformNames={youtube:'YouTube',instagram:'Instagram',x:'X'};let editingReference=null,referenceMediaBusy=false,referenceObserver=null;
function parseReference(input){let u;try{u=new URL(input.trim().match(/^https?:\/\//i)?input.trim():'https://'+input.trim())}catch{throw Error('Paste a valid video or post link.')}if(!['https:','http:'].includes(u.protocol)||u.username||u.password||u.port)throw Error('Use a direct YouTube, Instagram, or X link.');const host=u.hostname.toLowerCase().replace(/^www\./,'');let id,platform,url,embed;
if(['youtube.com','m.youtube.com','youtu.be'].includes(host)){id=host==='youtu.be'?u.pathname.split('/')[1]:u.pathname==='/watch'?u.searchParams.get('v'):u.pathname.match(/^\/(?:shorts|embed|live)\/([\w-]+)/)?.[1];if(!/^[\w-]{11}$/.test(id||''))throw Error('Use a YouTube video or Shorts link, not a channel or playlist.');platform='youtube';url='https://www.youtube.com/watch?v='+id;const t=u.searchParams.get('t')||u.searchParams.get('start')||'';let seconds=0;if(/^\d+$/.test(t))seconds=Number(t);else if(/^(?:\d+h)?(?:\d+m)?(?:\d+s)?$/.test(t))seconds=Number(t.match(/(\d+)h/)?.[1]||0)*3600+Number(t.match(/(\d+)m/)?.[1]||0)*60+Number(t.match(/(\d+)s/)?.[1]||0);seconds=Math.min(seconds,86400);if(seconds)url+='&t='+seconds;embed='https://www.youtube-nocookie.com/embed/'+id+'?playsinline=1'+(seconds?'&start='+seconds:'');}
else if(['instagram.com','m.instagram.com'].includes(host)){const match=u.pathname.match(/^\/(p|reel|reels|tv)\/([\w-]+)(?:\/|$)/);if(!match)throw Error('Use the direct Instagram post or Reel link. Share redirect links and Stories cannot be embedded.');id=match[2];platform='instagram';url='https://www.instagram.com/'+(match[1]==='reels'?'reel':match[1])+'/'+id+'/';embed=url+'embed/';}
else if(['x.com','twitter.com','mobile.twitter.com','mobile.x.com'].includes(host)){id=u.pathname.match(/^\/(?:[\w]+|i\/web)\/status\/(\d+)(?:\/|$)/)?.[1];if(!id)throw Error('Use a direct X post link containing /status/.');platform='x';url='https://x.com/i/web/status/'+id;embed='https://platform.twitter.com/embed/Tweet.html?id='+id+'&dnt=true&theme=light';}
else throw Error('Supported platforms: YouTube, Instagram, and X.');return {platform,url,embed,key:platform+':'+id,externalId:id};}
function validateReferences(refs){if(!Array.isArray(refs)||refs.length>10000)throw Error('Invalid reference library in backup.');return refs.map(r=>{const parsed=parseReference(String(r.url||''));return {...parsed,id:uuid(),title:String(r.title||platformNames[parsed.platform]+' reference').slice(0,200),notes:String(r.notes||'').slice(0,20000),tags:Array.isArray(r.tags)?r.tags.map(t=>String(t).slice(0,60)).slice(0,30):[],cover:validateReferenceMedia(r.cover,'image'),video:validateReferenceMedia(r.video,'video'),videoName:String(r.videoName||'').slice(0,200),createdAt:typeof r.createdAt==='string'?r.createdAt:new Date().toISOString()}})}
