function renderReferences(){if(!state)return;referenceObserver?.disconnect();const refs=state.references||[],query=$('referenceSearch').value.toLowerCase().trim(),platform=$('referencePlatform').value;const visible=refs.filter(r=>(platform==='all'||r.platform===platform)&&[r.title,r.notes,...r.tags].join(' ').toLowerCase().includes(query));$('referenceCount').textContent=visible.length+' / '+refs.length+' references';$('referenceGrid').innerHTML=visible.length?visible.map(r=>`<article class="reference-card"><div class="reference-player" id="player-${r.id}"><button class="reference-play ${r.platform}" data-play-reference="${r.id}" aria-label="Play ${esc(r.title)}">${referenceCover(r)?`<img class="reference-cover" src="${esc(referenceCover(r))}" alt="${esc(r.title)}" loading="lazy">`:``}<span class="platform-mark">▶</span><span class="reference-play-caption">${r.video?"Play video":"Play "+platformNames[r.platform]+" reference"}</span></button></div><div class="reference-body"><span class="eyebrow">${platformNames[r.platform]}</span><h3>${esc(r.title)}</h3><p>${esc(r.notes)}</p><div class="reference-tags">${r.tags.map(t=>`<span class="pill">${esc(t)}</span>`).join('')}</div><div class="reference-actions"><button class="text-button" data-edit-reference="${r.id}">Edit reference</button><a class="text-button" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open original ↗</a></div></div></article>`).join(''):`<section class="empty"><div class="empty-symbol"></div><h2>${refs.length?'No matching references.':'Keep your inspiration close.'}</h2><p>${refs.length?'Try another search or platform.':'Paste a video link above to start your reference library. Add a title, notes, and tags so you can find it when you need it.'}</p></section>`;loadVisibleReferencePreviews();}
