function validateReferenceMedia(value,type){if(!value)return '';if(typeof value!=='string'||value.length>(type==='image'?8:115)*1024*1024)throw Error('Reference media in backup is too large.');const pattern=type==='image'?/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/:/^data:video\/(mp4|webm);base64,[A-Za-z0-9+/=]+$/;if(!pattern.test(value))throw Error('Unsupported reference media in backup.');return value}
