function updateReferenceMediaState(r){$('refCoverState').textContent=r.cover?'Custom cover saved.':r.platform==='youtube'?'YouTube thumbnail shown automatically.':'Add a screenshot or attach the video to see a thumbnail.';$('refVideoState').textContent=r.video?'Attached: '+(r.videoName||'video')+' · clean video-only player':'Using the platform embed.'}
function readMediaData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read this file.'));reader.readAsDataURL(file)})}
async function captureVideoCover(file){const url=URL.createObjectURL(file),v=document.createElement('video');v.muted=true;v.preload='auto';v.src=url;try{return await new Promise((resolve,reject)=>{const timer=setTimeout(()=>finish(null),10000);function finish(result){clearTimeout(timer);v.onloadeddata=null;v.onseeked=null;v.onerror=null;result?resolve(result):reject(Error('Could not capture a frame. Add a cover image manually.'))}function capture(){try{const c=document.createElement('canvas');const scale=Math.min(1,960/v.videoWidth);c.width=Math.round(v.videoWidth*scale);c.height=Math.round(v.videoHeight*scale);if(!c.width||!c.height)return finish(null);c.getContext('2d').drawImage(v,0,0,c.width,c.height);finish(c.toDataURL('image/jpeg',.85))}catch{finish(null)}}v.onloadeddata=()=>{if(v.duration>.15){v.onseeked=capture;v.currentTime=Math.min(.3,v.duration/2)}else capture()};v.onerror=()=>finish(null)})}finally{v.removeAttribute('src');v.load();URL.revokeObjectURL(url)}}
