$('refCoverFile').onchange=e=>attachReferenceMedia('cover',e.target.files[0]);$('refVideoFile').onchange=e=>attachReferenceMedia('video',e.target.files[0]);
for(const [id,key] of [['clearRefCover','cover'],['clearRefVideo','video']])$(id).onclick=async()=>{if(referenceMediaBusy)return;const r=state.references.find(x=>x.id===editingReference);if(!r)return;r[key]='';if(key==='video')r.videoName='';await save();updateReferenceMediaState(r);renderReferences()};
