function loadVisibleReferencePreviews(){const candidates=[...$('referenceGrid').querySelectorAll('[data-play-reference]')].filter(b=>{const r=state.references.find(r=>r.id===b.dataset.playReference);return r&&!r.video&&!referenceCover(r)});function reveal(button){const r=state.references.find(r=>r.id===button.dataset.playReference);if(!r||!button.isConnected)return;const host=$('player-'+r.id),frame=document.createElement('iframe');frame.src=parseReference(r.url).embed;frame.title=r.title+' — video preview';frame.allow='encrypted-media; picture-in-picture; fullscreen';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';host.classList.add('portrait-player');host.replaceChildren(frame)}if(!('IntersectionObserver' in window)){candidates.forEach(reveal);return}referenceObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){referenceObserver.unobserve(entry.target);reveal(entry.target)}},{rootMargin:'300px'});candidates.forEach(b=>referenceObserver.observe(b));}

let extractorVideo=null, extractedFrames=[];
