$('extractorNav').onclick=()=>showExtractor(true);$('extractVideoBtn').onclick=()=>$('extractVideo').click();$('extractEmptyBtn').onclick=()=>$('extractVideo').click();$('extractReset').onclick=()=>{$('extractVideo').click()};$('extractVideo').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>300*1024*1024)return toast('Choose a video under 300 MB.');try{extractorVideo=URL.createObjectURL(f);const v=document.createElement('video');v.src=extractorVideo;v.preload='metadata';await new Promise((r,j)=>{v.onloadedmetadata=r;v.onerror=()=>j(Error('This video could not be read in your browser.'))});$('extractName').textContent=f.name;$('extractFolderName').value=f.name.replace(/\.[^.]+$/,'')+' — Storyboard';$('extractInfo').textContent=` · ${fmt(v.duration)}s · ${v.videoWidth} × ${v.videoHeight}`;$('extractEmpty').hidden=true;$('extractWorkspace').hidden=false;$('extractStatus').textContent='Ready';$('frameGrid').innerHTML='';extractedFrames=[];window.extractorMedia=v}catch(e){toast(e.message)}};
$('runExtract').onclick=async()=>{const v=window.extractorMedia;if(!v)return;const interval=Number($('extractInterval').value),dedupe=$('extractDedupe').value!=='off',frames=[],seen=[];const canvas=document.createElement('canvas'),scale=Math.min(1,1280/Math.max(v.videoWidth,v.videoHeight));canvas.width=Math.max(1,Math.round(v.videoWidth*scale));canvas.height=Math.max(1,Math.round(v.videoHeight*scale));const ctx=canvas.getContext('2d',{willReadFrequently:true}),total=Math.max(1,Math.ceil(v.duration/interval));$('runExtract').disabled=true;$('extractStatus').textContent='Extracting…';for(let i=0;i<total;i++){const t=Math.min(Math.max(0,i*interval),Math.max(0,v.duration-.03));await seekVideo(v,t);ctx.drawImage(v,0,0,canvas.width,canvas.height);const data=ctx.getImageData(0,0,32,18).data;let diff=seen.length?0:Infinity;if(seen.length){const prev=seen[seen.length-1];for(let j=0;j<data.length;j+=4)diff+=(Math.abs(data[j]-prev[j])+Math.abs(data[j+1]-prev[j+1])+Math.abs(data[j+2]-prev[j+2]))/3;diff/=data.length/4}if(!dedupe||diff>10||!seen.length){const thumb=canvas.toDataURL('image/jpeg',.84);frames.push({id:uuid(),time:t,src:thumb});seen.push(data)}$('extractStatus').textContent=`${i+1} / ${total}`}extractedFrames=frames;renderExtractedFrames(total-frames.length);$('runExtract').disabled=false;$('extractStatus').textContent='Done';};
function seekVideo(v,t){return new Promise((r,j)=>{const done=()=>{v.removeEventListener('seeked',done);v.removeEventListener('error',fail);r()};const fail=()=>{v.removeEventListener('seeked',done);v.removeEventListener('error',fail);j(Error('Could not seek this video.'))};v.addEventListener('seeked',done,{once:true});v.addEventListener('error',fail,{once:true});v.currentTime=t})}
function renderExtractedFrames(removed=0){$('extractedCount').textContent=String(extractedFrames.length).padStart(2,'0');$('duplicateCount').textContent=String(removed).padStart(2,'0');$('frameGrid').innerHTML=extractedFrames.map((f,i)=>`<label class="extracted-card"><input type="checkbox" data-frame-check="${f.id}" checked><img src="${f.src}" alt="Frame at ${fmt(f.time)} seconds"><span>FRAME ${String(i+1).padStart(2,'0')} · ${fmt(f.time)}s</span></label>`).join('')||'<p class="hint">No frames extracted. Try keeping every sampled frame.</p>'}
$('selectAllFrames').onclick=()=>{$('frameGrid').querySelectorAll('input[type=checkbox]').forEach(c=>c.checked=true)};$('sendFrames').onclick=async()=>{const frames=extractedFrames.filter(f=>$('frameGrid').querySelector(`[data-frame-check="${f.id}"]`)?.checked);if(!frames.length)return toast('Select at least one frame.');const p=project(),folder={id:uuid(),title:$('extractFolderName').value.trim()||$('extractName').textContent.replace(/\.[^.]+$/,'')+' — Storyboard'};p.folders||=[];p.folders.push(folder);const added=frames.map((f,i)=>({...freshShot(`Frame ${i+1} · ${fmt(f.time)}s`),folderId:folder.id,src:f.src,width:window.extractorMedia.videoWidth,height:window.extractorMedia.videoHeight,notes:`Source: ${$('extractName').textContent} · ${fmt(f.time)} seconds`}));p.shots.push(...added);$('sendFrames').disabled=true;try{await save();activeFolder=null;showExtractor(false);render();toast(`${frames.length} frames saved in “${folder.title}”. Click the folder to open them.`)}catch{p.folders=p.folders.filter(f=>f.id!==folder.id);p.shots=p.shots.filter(s=>s.folderId!==folder.id)}finally{$('sendFrames').disabled=false}};

async function generateFramePrompts(s,targets,revision=''){
 const selectedStyle=s.mjStyle||'';
 const result=await agentPrompts(s,targets,{camera:cameraText[s.camera],revision,save,onProgress:t=>{$('promptFeedback').textContent=t}});
 for(const t of targets)s.prompts[t]=t==='midjourney'?applyStyle(result.prompts[t],selectedStyle):result.prompts[t];if(s.status==='draft')s.status='prompted';await save();
 $('promptFeedback').textContent='Saved from Livepeer Agent.'+(result.limitations.length?' '+result.limitations.join(' '):'');
}
